; =============================================================================
; runtime.asm — routines embedded in every executable generated by nihilc.
;
; Assembled with `nasm -f bin` and included in the compiler with incbin. It is copied
; byte by byte to offset SIZE_HEADER of the executable, which is the entry
; point; that is why `org` is the final virtual address.
;
; Convention: routines may destroy rax, rcx, rdx, rsi, rdi, r8–r11 and
; preservam rbx, rbp, rsp, r12–r15.
; =============================================================================

bits 64
default abs                         ; data at a fixed absolute address
%include "layout.inc"
org BASE_CODE + SIZE_HEADER

start:
    db 0xE9
    dd 0                            ; jmp program — patched by nihilc

; ---- jump table (fixed offsets, see layout.inc) -----------------------
t_div:          jmp strict near rt_div             ; RT_DIV
t_mod:          jmp strict near rt_mod             ; RT_MOD
t_print_int:  jmp strict near rt_print_int     ; RT_IMPRIME_INT
t_print_bool: jmp strict near rt_print_bool    ; RT_IMPRIME_BOOL
t_print_str:  jmp strict near rt_print_str     ; RT_IMPRIME_STR
t_exit:         jmp strict near rt_exit            ; RT_SAIR
t_error:         jmp strict near rt_error            ; RT_ERRO
t_alloc:        jmp strict near rt_alloc           ; RT_ALOCA
t_array_rep:    jmp strict near rt_array_rep       ; RT_ARRAY_REP
t_error_index:  jmp strict near rt_error_index     ; RT_ERRO_INDICE
t_write_byte: jmp strict near rt_write_byte    ; RT_ESCREVE_BYTE
t_read_byte:      jmp strict near rt_read_byte         ; RT_LE_BYTE
t_str_equal:    jmp strict near rt_str_equal       ; RT_STR_IGUAL
t_error_int:     jmp strict near rt_error_int        ; RT_ERRO_INT
t_error_bool:    jmp strict near rt_error_bool       ; RT_ERRO_BOOL
t_error_str:     jmp strict near rt_error_str        ; RT_ERRO_STR
t_read_file:   jmp strict near rt_read_file      ; RT_LE_ARQUIVO
t_text:        jmp strict near rt_text           ; RT_TEXTO
t_print_int_opt:  jmp strict near rt_print_int_opt ; RT_IMPRIME_INT_OPC
t_print_bool_opt: jmp strict near rt_print_bool_opt ; RT_IMPRIME_BOOL_OPC
t_print_str_opt:  jmp strict near rt_print_str_opt ; RT_IMPRIME_STR_OPC
t_err_int_opt:  jmp strict near rt_error_int_opt    ; RT_ERRO_INT_OPC
t_err_bool_opt: jmp strict near rt_error_bool_opt   ; RT_ERRO_BOOL_OPC
t_err_str_opt:  jmp strict near rt_error_str_opt    ; RT_ERRO_STR_OPC
t_read_file_opt:   jmp strict near rt_read_file_opt  ; RT_LE_ARQUIVO_OPC
t_concat:       jmp strict near rt_concat          ; RT_CONCAT
t_sleep:        jmp strict near rt_sleep           ; RT_SLEEP
t_write_file:   jmp strict near rt_write_file      ; RT_WRITE_FILE
t_append_file:  jmp strict near rt_append_file     ; RT_APPEND_FILE
t_read_at:      jmp strict near rt_read_at         ; RT_READ_AT
t_write_at:     jmp strict near rt_write_at        ; RT_WRITE_AT
t_write_at_ns:  jmp strict near rt_write_at_ns     ; RT_WRITE_AT_NS
t_truncate:     jmp strict near rt_truncate        ; RT_TRUNCATE
t_truncate_ns:  jmp strict near rt_truncate_ns     ; RT_TRUNCATE_NS
t_int_text:     jmp strict near rt_int_text        ; RT_INT_TEXT
t_array_concat: jmp strict near rt_array_concat    ; RT_ARRAY_CONCAT

; ---- arithmetic -------------------------------------------------------------
; Division truncated toward zero (as in C). MIN / -1 gives MIN (idiv
; would raise SIGFPE) and MIN % -1 gives 0.
rt_div:
    test rcx, rcx
    jz error_div_zero
    cmp rcx, -1
    je .minus_one
    cqo
    idiv rcx
    ret
.minus_one:
    neg rax
    ret

rt_mod:
    test rcx, rcx
    jz error_div_zero
    cmp rcx, -1
    je .zero
    cqo
    idiv rcx
    mov rax, rdx
    ret
.zero:
    xor eax, eax
    ret

error_div_zero:
    lea rsi, [rel s_div_zero]
    jmp rt_error

; ---- output ------------------------------------------------------------------
rt_print_int:
    sub rsp, 32
    lea rdi, [rsp + 32]
    call rt_decimal
    lea rdx, [rsp + 32]
    sub rdx, rsi
    call rt_buffer
    add rsp, 32
    ret

; rt_decimal: rax = signed value, rdi = end of a buffer (≥ 20 bytes before it)
; → rsi = start of the digits. Destroys rax, rcx, rdx, r8.
rt_decimal:
    mov r8, rax
    test rax, rax
    jns .positive
    neg rax                         ; MIN stays MIN, but the unsigned div gets it right
.positive:
    mov ecx, 10
.digit:
    xor edx, edx
    div rcx
    add dl, '0'
    dec rdi
    mov [rdi], dl
    test rax, rax
    jnz .digit
    test r8, r8
    jns .finish
    dec rdi
    mov byte [rdi], '-'
.finish:
    mov rsi, rdi
    ret

; rt_array_concat: rax = a, rcx = b (ARRAYs of one type) → a new ARRAY with
; the elements of a and then those of b
rt_array_concat:
    push rbx
    push r12
    mov rbx, rax
    mov r12, rcx
    mov rcx, [rbx - 8]
    add rcx, [r12 - 8]
    call rt_alloc
    mov rdi, rax
    mov rsi, rbx
    mov rcx, [rbx - 8]
    rep movsq
    mov rsi, r12
    mov rcx, [r12 - 8]
    rep movsq
    pop r12
    pop rbx
    ret

; rt_int_text: rax = INT → rax = a new STRING with it in decimal ($n)
rt_int_text:
    push rbx
    sub rsp, 32
    lea rdi, [rsp + 32]
    call rt_decimal                 ; rsi = the first character
    lea rbx, [rsp + 32]
    sub rbx, rsi                    ; length
    push rsi
    lea rcx, [rbx + 8]
    shr rcx, 3
    call rt_alloc
    pop rsi
    mov [rax - 8], rbx
    mov rdi, rax
    mov rcx, rbx
    rep movsb
    add rsp, 32
    pop rbx
    ret

rt_print_bool:
    test rax, rax
    jz .falso_
    lea rsi, [rel s_true]
    mov edx, 4
    jmp rt_buffer
.falso_:
    lea rsi, [rel s_false]
    mov edx, 5
    jmp rt_buffer

rt_print_str:
    mov rsi, rax
    mov rdx, [rax - 8]
    jmp rt_buffer

; rt_buffer: rsi = ptr, rdx = len — copies into the buffer, flushing it when full
rt_buffer:
.repeat:
    test rdx, rdx
    jz .finish
    mov rax, [OUTPUT_SIZE]
    mov ecx, OUTPUT_CAP
    sub rcx, rax                    ; free space
    jnz .copy
    push rsi
    push rdx
    call rt_flush
    pop rdx
    pop rsi
    jmp .repeat
.copy:
    cmp rcx, rdx
    jbe .count
    mov rcx, rdx
.count:
    mov rdi, OUTPUT_BUF
    add rdi, rax
    add rax, rcx
    mov [OUTPUT_SIZE], rax
    sub rdx, rcx
    rep movsb
    jmp .repeat
.finish:
    ret

rt_flush:
    mov rdx, [OUTPUT_SIZE]
    test rdx, rdx
    jz .finish
    mov edi, 1
    mov rsi, OUTPUT_BUF
    call rt_write_fd
    mov qword [OUTPUT_SIZE], 0
.finish:
    ret

; rt_write_fd: edi = fd, rsi = ptr, rdx = len (gives up on error)
rt_write_fd:
.repeat:
    test rdx, rdx
    jz .finish
    mov eax, 1                      ; sys_write
    syscall
    test rax, rax
    jle .finish
    add rsi, rax
    sub rdx, rax
    jmp .repeat
.finish:
    ret

; ---- termination ----------------------------------------------------------------
rt_exit:                            ; rdi = exit code
    push rdi
    call rt_flush
    pop rdi
    mov eax, 60                     ; sys_exit
    syscall

; rt_error: rsi = message (0-terminated). Writes "nihil: <msg>\n" to stderr
; and exits with code 2 (SPEC §8.3).
rt_error:
    push rsi
    call rt_flush
    mov edi, 2
    lea rsi, [rel s_nihil]
    mov edx, s_nihil_len
    call rt_write_fd
    pop rsi
    xor edx, edx
.size:
    cmp byte [rsi + rdx], 0
    je .write
    inc rdx
    jmp .size
.write:
    mov edi, 2
    call rt_write_fd
    mov edi, 2
    lea rsi, [rel s_nl]
    mov edx, 1
    call rt_write_fd
    mov eax, 60
    mov edi, 2
    syscall

; ---- arrays and heap ----------------------------------------------------------
; An array is [length: 8 bytes][8-byte elements]; the value of the array points
; to the first element. A STRING is the same block with its length in bytes.
;
; Garbage collector: conservative mark and sweep. Values carry no type at run
; time, so every qword in the registers, on the stack, in the globals and in a
; live block is taken as a possible reference: if it points into a block of the
; heap, that block stays. What no path reaches is freed and its memory used again.
;
; The heap is one reservation of address space (64 GiB, or less if refused) in
; 64 KiB pages, each described by one qword in GC_DESC:
;   0           free (or never used)
;   PD_SMALL    blocks of one size class (class in the bits above the kind)
;   PD_LARGE    first page of a large block (its pages above the kind)
;   PD_CONT     a later page of a large block (pages back to the first one)
;   PD_DIRTY    an empty page of small blocks kept for reuse without giving it
;               back (up to GC_KEEP of them): its old bytes are cleared on reuse
; Small blocks (up to 32 KiB) come in 21 size classes: 32, 48, 64, 96, 128 …
; 32768 bytes. A block starts with a header [n << 8 | marked << 1 | used] and
; then the length word the program sees, so the value points 16 bytes in.
; Free small blocks have header 0 and link to the next free one at +8.
; New memory is always zero: fresh pages come zeroed from the kernel, freed
; pages are given back with madvise(MADV_DONTNEED) (zero again when touched),
; and a reused small block is cleared before it is handed out. A large block
; is scanned only where the kernel has memory for it (mincore): a big array
; never written costs nothing, as before.
%define GC_PAGE_SHIFT 16
%define GC_PAGE       (1 << GC_PAGE_SHIFT)
%define GC_SMALL_MAX  32768
%ifdef GC_STRESS                    ; make gcstress: a collection every 256 KiB
%define GC_MIN        (256 << 10)
%else
%define GC_MIN        (16 << 20)    ; collect after at least 16 MiB of new blocks
%endif
%define GC_RESERVE    (64 << 30)
%define PD_SMALL 1
%define PD_LARGE 2
%define PD_CONT  3
%define PD_DIRTY 4
%define GC_KEEP  (GC_MIN >> GC_PAGE_SHIFT)   ; empty small pages kept: 16 MiB

rt_alloc:                           ; rcx = n → rax (keeps every register but rax, rdx, r8)
    test rcx, rcx
    js .negativo
    mov rax, 1 << 40
    cmp rcx, rax
    jae .large
    push rcx
    push rsi
    push rdi
    push r9
    push r10
    push r11
    cmp qword [GC_STATE], 0
    jne .ready
    call gc_init
.ready:
    mov r11, rcx                    ; n
    lea rdx, [rcx * 8 + 16]         ; bytes, with the header and the length
    add [GC_ALLOCATED], rdx
    mov rax, [GC_ALLOCATED]
    cmp rax, [GC_THRESHOLD]
    jbe .alloc
    call gc_collect                 ; keeps every register
.alloc:
    cmp rdx, GC_SMALL_MAX
    ja .big
    xor r8d, r8d                    ; the size class: 32, 48, 64, 96, 128, 192 …
    cmp rdx, 32
    jbe .class
    lea r9, [rdx - 1]
    bsr r9, r9                      ; 2^b < bytes <= 2^(b+1)
    lea ecx, [r9 - 1]
    mov r10d, 3
    shl r10, cl                     ; 3 · 2^(b-1)
    lea r8, [r9 * 2 - 9]
    cmp rdx, r10
    jbe .class
    inc r8                          ; 2^(b+1)
.class:
    mov rax, [GC_FREE + r8 * 8]
    test rax, rax
    jnz .take
    call gc_small_page              ; a new page of free blocks of class r8
    mov rax, [GC_FREE + r8 * 8]
.take:
    mov r9, [rax + 8]
    mov [GC_FREE + r8 * 8], r9
    mov r9, rax                     ; clear the n elements (and the 0 after a STRING)
    lea rdi, [rax + 16]
    mov rcx, r11
    xor eax, eax
    rep stosq
    mov rax, r9
    jmp .header
.big:
    lea rcx, [rdx + GC_PAGE - 1]
    shr rcx, GC_PAGE_SHIFT          ; pages
    call gc_get_pages
    test rax, rax
    jnz .pages
    call gc_collect
    call gc_get_pages
    test rax, rax
    jz .without_memory
.pages:                             ; zero already: only the descriptors and the header
    mov r9, rax
    sub r9, [GC_HEAP_BASE]
    shr r9, GC_PAGE_SHIFT
    mov rdi, [GC_DESC]
    lea rdi, [rdi + r9 * 8]
    mov r10, rcx
    shl r10, 8
    or r10, PD_LARGE
    mov [rdi], r10
    mov r10d, 1
.cont:
    cmp r10, rcx
    jae .header
    mov r9, r10
    shl r9, 8
    or r9, PD_CONT
    mov [rdi + r10 * 8], r9
    inc r10
    jmp .cont
.header:
    mov rcx, r11
    shl rcx, 8
    or rcx, 1                       ; used
    mov [rax], rcx
    mov [rax + 8], r11              ; the length
    add rax, 16
    pop r11
    pop r10
    pop r9
    pop rdi
    pop rsi
    pop rcx
    ret
.negativo:
    lea rsi, [rel s_size_negativo]
    jmp rt_error
.large:
    lea rsi, [rel s_size_large]
    jmp rt_error
.without_memory:
    lea rsi, [rel s_without_memory]
    jmp rt_error

gc_class_size:
    dq 32, 48, 64, 96, 128, 192, 256, 384, 512, 768, 1024, 1536, 2048, 3072
    dq 4096, 6144, 8192, 12288, 16384, 24576, 32768

; r8 = class: puts a new page of free blocks of that class in its list
; (collecting first if there is no page left). Keeps every register but rax.
gc_small_page:
    push rcx
    push rdx
    push rsi
    push r9
    push r10
    mov rax, [GC_NDIRTY]            ; an empty page kept from a collection
    test rax, rax
    jz .fresh
    dec rax
    mov [GC_NDIRTY], rax
    mov rcx, [GC_DIRTY]
    mov rax, [rcx + rax * 8]
    shl rax, GC_PAGE_SHIFT
    add rax, [GC_HEAP_BASE]
    jmp .carve
.fresh:
    mov ecx, 1
    call gc_get_pages
    test rax, rax
    jnz .carve
    call gc_collect
    cmp qword [GC_FREE + r8 * 8], 0 ; the collection may have freed blocks of this class
    jne .done
    mov ecx, 1
    call gc_get_pages
    test rax, rax
    jz rt_alloc.without_memory
.carve:
    mov rsi, rax                    ; the page
    mov rcx, rax
    sub rcx, [GC_HEAP_BASE]
    shr rcx, GC_PAGE_SHIFT
    mov r9, [GC_DESC]
    mov r10, r8
    shl r10, 8
    or r10, PD_SMALL
    mov [r9 + rcx * 8], r10
    lea r9, [rel gc_class_size]
    mov r9, [r9 + r8 * 8]           ; block size
    mov eax, GC_PAGE
    xor edx, edx
    div r9
    imul rax, r9                    ; past the last block that fits
    xor r10d, r10d                  ; the list, built from the end
.link:
    sub rax, r9
    lea rcx, [rsi + rax]
    mov qword [rcx], 0              ; free (a kept page still has old bytes)
    mov [rcx + 8], r10
    mov r10, rcx
    test rax, rax
    jnz .link
    mov [GC_FREE + r8 * 8], r10
.done:
    pop r10
    pop r9
    pop rsi
    pop rdx
    pop rcx
    ret

; rcx = pages → rax = the first one (zeroed memory), or 0 if there is no room.
; First fit among the runs of free pages, else new pages. Keeps rcx; uses rdx, r9, r10.
gc_get_pages:
    mov r9, [GC_RUNS]
    xor r10d, r10d
.find:
    cmp r10, [GC_NRUNS]
    jae .new
    mov rax, r10
    shl rax, 4
    mov rdx, [r9 + rax + 8]         ; its pages
    cmp rdx, rcx
    jae .take
    inc r10
    jmp .find
.take:
    add r9, rax                     ; the run
    mov rax, [r9]                   ; its first page
    sub rdx, rcx
    jz .whole
    mov [r9 + 8], rdx               ; what is left starts after the pages taken
    lea rdx, [rax + rcx]
    mov [r9], rdx
    jmp .address
.whole:                             ; the last run takes its place
    mov rdx, [GC_NRUNS]
    dec rdx
    mov [GC_NRUNS], rdx
    shl rdx, 4
    add rdx, [GC_RUNS]
    mov r10, [rdx]
    mov [r9], r10
    mov r10, [rdx + 8]
    mov [r9 + 8], r10
.address:
    shl rax, GC_PAGE_SHIFT
    add rax, [GC_HEAP_BASE]
    ret
.new:
    mov rax, [GC_BUMP]
    mov rdx, rcx
    shl rdx, GC_PAGE_SHIFT
    add rdx, rax
    cmp rdx, [GC_HEAP_LIMIT]
    ja .none
    mov [GC_BUMP], rdx
    ret
.none:
    xor eax, eax
    ret

; gc_mmap: rsi = bytes → rax = new zeroed memory (address space only), or a
; negative errno. Uses rcx, rdx, rdi, r8–r11.
gc_mmap:
    mov eax, 9                      ; sys_mmap
    xor edi, edi
    mov edx, 3                      ; PROT_READ | PROT_WRITE
    mov r10d, 0x4022                ; MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE
    mov r8, -1
    xor r9d, r9d
    syscall
    ret

; the first allocation: reserves the heap and its tables, finds the roots
gc_init:
    push rax
    push rcx
    push rdx
    push rsi
    push rdi
    push r8
    push r9
    push r10
    push r11
    push rbx
    mov rbx, GC_RESERVE
.reserve:
    lea rsi, [rbx + GC_PAGE]        ; one page more, to align the start
    call gc_mmap
    cmp rax, -4096
    jb .reserved
    shr rbx, 2                      ; refused: a quarter of that
    cmp rbx, 64 << 20
    jae .reserve
    jmp rt_alloc.without_memory
.reserved:
    add rax, GC_PAGE - 1
    and rax, -GC_PAGE
    mov [GC_HEAP_BASE], rax
    mov [GC_BUMP], rax
    add rax, rbx
    mov [GC_HEAP_LIMIT], rax
    mov rsi, rbx
    shr rsi, GC_PAGE_SHIFT - 3      ; 8 bytes per page
    call gc_mmap
    cmp rax, -4096
    jae rt_alloc.without_memory
    mov [GC_DESC], rax
    mov rsi, rbx
    shr rsi, GC_PAGE_SHIFT - 4      ; 16 bytes per run
    call gc_mmap
    cmp rax, -4096
    jae rt_alloc.without_memory
    mov [GC_RUNS], rax
    mov rsi, rbx
    shr rsi, 2                      ; a block has at least 32 bytes: 8 per block
    call gc_mmap
    cmp rax, -4096
    jae rt_alloc.without_memory
    mov [GC_MSTACK], rax
    add rax, rsi
    mov [GC_MSTACK_END], rax
    mov rsi, rbx
    shr rsi, GC_PAGE_SHIFT - 3      ; kept pages: 8 bytes per page
    call gc_mmap
    cmp rax, -4096
    jae rt_alloc.without_memory
    mov [GC_DIRTY], rax
    mov rsi, rbx
    shr rsi, 12                     ; mincore: a byte per 4 KiB
    call gc_mmap
    cmp rax, -4096
    jae rt_alloc.without_memory
    mov [GC_MINCORE], rax
    mov rax, [BASE_CODE + 64 + 56 + 16]   ; the data PT_LOAD: p_vaddr …
    add rax, [BASE_CODE + 64 + 56 + 40]   ; … + p_memsz
    mov [GC_DATA_END], rax
    call gc_stack_top
    mov [GC_STACK_TOP], rax
    mov rax, GC_MIN
    cmp qword [GC_STACK_TOP], 0
    jne .threshold
    mov rax, -1                     ; roots unknown: never collect
    shr rax, 1
.threshold:
    mov [GC_THRESHOLD], rax
    mov qword [GC_STATE], 1
    pop rbx
    pop r11
    pop r10
    pop r9
    pop r8
    pop rdi
    pop rsi
    pop rdx
    pop rcx
    pop rax
    ret

; → rax = an address above every frame of the program's stack, or 0: the
; file name the kernel put at the top of the stack (AT_EXECFN), from
; prctl(PR_GET_AUXV); else the end of "[stack]" in /proc/self/maps
gc_stack_top:
    push rbx
    push r12
    sub rsp, 1024
    mov eax, 157                    ; sys_prctl(PR_GET_AUXV, buffer, size)
    mov edi, 0x41555856
    mov rsi, rsp
    mov edx, 1024
    xor r10d, r10d
    xor r8d, r8d
    syscall
    test rax, rax
    jle .maps
    mov rcx, rsp
.aux:
    mov rdx, [rcx]
    test rdx, rdx                   ; AT_NULL
    jz .maps
    cmp rdx, 31                     ; AT_EXECFN
    je .execfn
    add rcx, 16
    jmp .aux
.execfn:
    mov rax, [rcx + 8]
    jmp .end
.maps:
    mov rsi, 1 << 20                ; the file, read into a temporary block
    call gc_mmap
    cmp rax, -4096
    jae .none
    mov rbx, rax
    lea rsi, [rel s_maps]
    mov eax, 257                    ; sys_openat(AT_FDCWD, "/proc/self/maps", O_RDONLY)
    mov rdi, -100
    xor edx, edx
    syscall
    test rax, rax
    js .free
    mov r12, rax
    xor ecx, ecx                    ; bytes read
.read:
    push rcx
    xor eax, eax                    ; sys_read
    mov rdi, r12
    lea rsi, [rbx + rcx]
    mov rdx, (1 << 20) - 1
    sub rdx, rcx
    syscall
    pop rcx
    test rax, rax
    jle .close
    add rcx, rax
    cmp rcx, (1 << 20) - 1
    jb .read
.close:
    push rcx
    mov eax, 3
    mov rdi, r12
    syscall
    pop rcx
    xor eax, eax                    ; looking for "[stack]"
    xor edx, edx                    ; start of the current line
.scan:
    lea rsi, [rax + 7]
    cmp rsi, rcx
    ja .not_found
    cmp byte [rbx + rax], 10
    jne .compare
    lea rdx, [rax + 1]
.compare:
    cmp dword [rbx + rax], '[sta'
    jne .next
    cmp dword [rbx + rax + 3], 'ack]'
    je .line
.next:
    inc rax
    jmp .scan
.line:                              ; "start-end …": the hexadecimal after '-'
    cmp byte [rbx + rdx], '-'
    je .hex
    inc rdx
    jmp .line
.hex:
    inc rdx
    xor eax, eax
.digit:
    movzx ecx, byte [rbx + rdx]
    sub ecx, '0'
    cmp ecx, 9
    jbe .add
    sub ecx, 'a' - '0' - 10
    cmp ecx, 10
    jb .found
    cmp ecx, 15
    ja .found
.add:
    shl rax, 4
    add rax, rcx
    inc rdx
    jmp .digit
.not_found:
    xor eax, eax
.found:
    push rax
    mov eax, 11                     ; sys_munmap
    mov rdi, rbx
    mov rsi, 1 << 20
    syscall
    pop rax
    jmp .end
.free:
    mov eax, 11
    mov rdi, rbx
    mov rsi, 1 << 20
    syscall
.none:
    xor eax, eax
.end:
    add rsp, 1024
    pop r12
    pop rbx
    ret

; a collection: keeps every register (they are roots, so they go on the stack
; that is scanned)
gc_collect:
    push rax
    push rbx
    push rcx
    push rdx
    push rsi
    push rdi
    push rbp
    push r8
    push r9
    push r10
    push r11
    push r12
    push r13
    push r14
    push r15
    mov r14, [GC_HEAP_BASE]
    mov r13, [GC_BUMP]
    sub r13, r14                    ; bytes of the heap in use (pages handed out)
    mov r12, [GC_DESC]
    mov r15, [GC_MSTACK]
    mov rsi, rsp                    ; the stack, with the registers just pushed
    mov rdi, [GC_STACK_TOP]
    call gc_scan
    mov rsi, GLOBALS
    mov rdi, [GC_DATA_END]
    call gc_scan
.drain:                             ; the blocks reached, until none is left
    cmp r15, [GC_MSTACK]
    je .sweep
    sub r15, 8
    mov rbx, [r15]
    mov rcx, [rbx]
    shr rcx, 8                      ; n
    lea rsi, [rbx + 16]
    lea rdi, [rsi + rcx * 8]
    cmp rcx, GC_SMALL_MAX / 8
    ja .large
    call gc_scan
    jmp .drain
.large:
    call gc_scan_resident
    jmp .drain
.sweep:
    call gc_sweep
    inc qword [GC_COUNT]
    mov qword [GC_ALLOCATED], 0
%ifdef GC_STRESS
    mov eax, GC_MIN
%else
    mov rax, [GC_LIVE]              ; the next one after as many new bytes as are in use
    cmp rax, GC_MIN
    jae .threshold
    mov eax, GC_MIN
%endif
.threshold:
    mov [GC_THRESHOLD], rax
    pop r15
    pop r14
    pop r13
    pop r12
    pop r11
    pop r10
    pop r9
    pop r8
    pop rbp
    pop rdi
    pop rsi
    pop rdx
    pop rcx
    pop rbx
    pop rax
    ret

; every qword in [rsi, rdi) that points into a used block marks it and puts it
; on the mark stack (r15). r12 = descriptors, r13 = heap bytes, r14 = heap.
gc_scan:
    lea rax, [rsi + 8]
    cmp rax, rdi
    ja .done
    mov rax, [rsi]
    add rsi, 8
    sub rax, r14
    cmp rax, r13
    jae gc_scan                     ; not in the heap (most values)
    mov r8, rax
    shr r8, GC_PAGE_SHIFT
    mov r9, [r12 + r8 * 8]
    movzx ecx, r9b
    cmp ecx, PD_SMALL
    je .small
    cmp ecx, PD_LARGE
    je .large
    cmp ecx, PD_CONT
    jne gc_scan
    shr r9, 8
    sub r8, r9                      ; the first page of the block
.large:
    shl r8, GC_PAGE_SHIFT
    lea r9, [r14 + r8]
    jmp .mark
.small:
    shr r9, 8
    lea rcx, [rel gc_class_size]
    mov r9, [rcx + r9 * 8]          ; block size
    and eax, GC_PAGE - 1            ; offset in the page
    xor edx, edx
    div r9
    imul rax, r9                    ; offset of the block
    lea rcx, [rax + r9]
    cmp rcx, GC_PAGE
    ja gc_scan                      ; the unused end of the page
    shl r8, GC_PAGE_SHIFT
    add rax, r8
    lea r9, [r14 + rax]
.mark:
    mov rax, [r9]
    test al, 1
    jz gc_scan                      ; a free block
    test al, 2
    jnz gc_scan                     ; already marked
    or rax, 2
    mov [r9], rax
    cmp r15, [GC_MSTACK_END]
    jae .overflow
    mov [r15], r9
    add r15, 8
    jmp gc_scan
.done:
    ret
.overflow:
    lea rsi, [rel s_without_memory]
    jmp rt_error

; gc_scan of a large block [rsi, rdi), skipping the 4 KiB pages the kernel has
; no memory for (never written: zero, so they hold no references)
gc_scan_resident:
    push rbx
    push rbp
    mov rbx, rsi
    and rbx, -4096                  ; first page
    mov rbp, rdi                    ; end
    mov rsi, rdi
    sub rsi, rbx
    add rsi, 4095                   ; bytes, in whole pages
    and rsi, -4096
    mov eax, 27                     ; sys_mincore(start, length, vector)
    mov rdi, rbx
    mov rdx, [GC_MINCORE]
    syscall
    test rax, rax
    jz .pages
    lea rsi, [rbx + 16]             ; mincore failed: scan it all
    mov rdi, rbp
    call gc_scan
    jmp .end
.pages:
    mov rdx, [GC_MINCORE]
.page:
    cmp rbx, rbp
    jae .end
    test byte [rdx], 1
    jz .next
    mov rsi, rbx
    lea rdi, [rbx + 4096]
    cmp rdi, rbp
    jbe .scan
    mov rdi, rbp
.scan:
    push rdx
    call gc_scan
    pop rdx
.next:
    add rbx, 4096
    inc rdx
    jmp .page
.end:
    pop rbp
    pop rbx
    ret

; frees what was not marked, clears the marks, rebuilds the free lists and the
; runs of free pages, and gives free pages back to the kernel
gc_sweep:
    xor eax, eax
.clear:
    mov qword [GC_FREE + rax * 8], 0
    inc eax
    cmp eax, 21
    jb .clear
    mov qword [GC_LIVE], 0
    mov qword [GC_NDIRTY], 0
    mov r11, r13
    shr r11, GC_PAGE_SHIFT          ; pages in use
    xor ebx, ebx                    ; page
.page:
    cmp rbx, r11
    jae .runs
    mov r9, [r12 + rbx * 8]
    movzx ecx, r9b
    cmp ecx, PD_SMALL
    je .small
    cmp ecx, PD_LARGE
    je .large
    cmp ecx, PD_DIRTY
    je .empty
    inc rbx
    jmp .page
.empty:                             ; an empty small page: kept, up to GC_KEEP
    mov rax, [GC_NDIRTY]
    cmp rax, GC_KEEP
    jae .give
    mov rcx, [GC_DIRTY]
    mov [rcx + rax * 8], rbx
    inc qword [GC_NDIRTY]
    mov qword [r12 + rbx * 8], PD_DIRTY
    inc rbx
    jmp .page
.give:
    mov qword [r12 + rbx * 8], 0    ; free: given back with its run
    inc rbx
    jmp .page
.large:
    shr r9, 8                       ; its pages
    mov rax, rbx
    shl rax, GC_PAGE_SHIFT
    lea rdi, [r14 + rax]
    mov rax, [rdi]
    test al, 2
    jz .free_large
    and rax, ~2
    mov [rdi], rax
    mov rax, r9
    shl rax, GC_PAGE_SHIFT
    add [GC_LIVE], rax
    add rbx, r9
    jmp .page
.free_large:
    mov qword [r12 + rbx * 8], 0
    inc rbx
    dec r9
    jnz .free_large
    jmp .page
.small:
    mov r10, r9
    shr r10, 8                      ; class
    lea rcx, [rel gc_class_size]
    mov r9, [rcx + r10 * 8]         ; block size
    mov rdi, rbx
    shl rdi, GC_PAGE_SHIFT
    add rdi, r14                    ; the page
    lea rsi, [rdi + GC_PAGE]
    sub rsi, r9                     ; the last block that fits starts at or before this
    xor edx, edx                    ; blocks still in use
    mov rcx, rdi
.pass1:
    cmp rcx, rsi
    ja .pass1_done
    mov rax, [rcx]
    test al, 2
    jz .not_marked
    and rax, ~2
    mov [rcx], rax
    inc edx
    jmp .pass1_next
.not_marked:
    mov qword [rcx], 0              ; unused (or freed now)
.pass1_next:
    add rcx, r9
    jmp .pass1
.pass1_done:
    test edx, edx
    jz .empty                       ; no block left
.keep:
    add qword [GC_LIVE], GC_PAGE
    mov rcx, rdi
    mov r8, [GC_FREE + r10 * 8]
.pass2:
    cmp rcx, rsi
    ja .pass2_done
    cmp qword [rcx], 0
    jne .pass2_next
    mov [rcx + 8], r8
    mov r8, rcx
.pass2_next:
    add rcx, r9
    jmp .pass2
.pass2_done:
    mov [GC_FREE + r10 * 8], r8
    inc rbx
    jmp .page
.runs:                              ; the free pages, in runs; the last run goes back to new
    mov qword [GC_NRUNS], 0
    xor ebx, ebx
.run_find:
    cmp rbx, r11
    jae .runs_done
    cmp qword [r12 + rbx * 8], 0
    je .run_start
    inc rbx
    jmp .run_find
.run_start:
    mov r10, rbx                    ; first page of the run
.run_end:
    inc rbx
    cmp rbx, r11
    jae .run_last
    cmp qword [r12 + rbx * 8], 0
    je .run_end
    mov rdx, [GC_NRUNS]             ; (first page, pages)
    shl rdx, 4
    add rdx, [GC_RUNS]
    mov [rdx], r10
    mov rax, rbx
    sub rax, r10
    mov [rdx + 8], rax
    inc qword [GC_NRUNS]
    call .give_back
    jmp .run_find
.run_last:                          ; a run at the end: those pages count as never used
    call .give_back
    mov rax, r10
    shl rax, GC_PAGE_SHIFT
    add rax, r14
    mov [GC_BUMP], rax
.runs_done:
    ret
.give_back:                         ; madvise(pages r10 … rbx, MADV_DONTNEED)
    push r11
    mov rdi, r10
    shl rdi, GC_PAGE_SHIFT
    add rdi, r14
    mov rsi, rbx
    sub rsi, r10
    shl rsi, GC_PAGE_SHIFT
    mov eax, 28                     ; sys_madvise
    mov edx, 4                      ; MADV_DONTNEED
    syscall
    pop r11
    ret

rt_array_rep:                       ; rcx = n, rdx = value → rax = [value ; n]
    push rdx
    call rt_alloc
    pop rdx
    test rdx, rdx                   ; zero: a new heap block already comes zeroed from the kernel
    jz .ready
    mov r8, rax
    mov rdi, rax
    mov rcx, [rax - 8]
    mov rax, rdx
    rep stosq
    mov rax, r8
.ready:
    ret

; rt_error_index: rax = array/STRING, rcx = index out of bounds
rt_error_index:
    push qword [rax - 8]            ; length
    push rcx
    call rt_flush
    mov edi, 2
    lea rsi, [rel s_nihil]
    mov edx, s_nihil_len
    call rt_write_fd
    mov edi, 2
    lea rsi, [rel s_index]
    mov edx, s_index_len
    call rt_write_fd
    pop rax
    call .number
    mov edi, 2
    lea rsi, [rel s_out]
    mov edx, s_out_len
    call rt_write_fd
    pop rax
    call .number
    mov edi, 2
    lea rsi, [rel s_close_nl]
    mov edx, 2
    call rt_write_fd
    mov eax, 60
    mov edi, 2
    syscall
.number:                            ; writes rax in decimal to stderr
    sub rsp, 32
    lea rdi, [rsp + 32]
    call rt_decimal
    lea rdx, [rsp + 32]
    sub rdx, rsi
    mov edi, 2
    call rt_write_fd
    add rsp, 32
    ret

; ---- bytes crus -------------------------------------------------------------
rt_write_byte:                    ; al
    mov rdx, [OUTPUT_SIZE]
    cmp rdx, OUTPUT_CAP
    jb .fits
    push rax
    call rt_flush
    pop rax
    xor edx, edx
.fits:
    mov [rdx + OUTPUT_BUF], al
    inc rdx
    mov [OUTPUT_SIZE], rdx
    ret

rt_read_byte:                         ; → rax = 0…255, or -1 at the end of input
    mov rcx, [IN_POS]
    cmp rcx, [IN_SIZE]
    jb .has
    cmp qword [IN_END], 0
    jne .finish
    call rt_flush                 ; what was already written appears before waiting
    xor eax, eax                    ; sys_read
    xor edi, edi
    mov rsi, IN_BUF
    mov edx, IN_CAP
    syscall
    test rax, rax
    jle .finished
    mov [IN_SIZE], rax
    xor ecx, ecx
.has:
    movzx eax, byte [rcx + IN_BUF]
    inc rcx
    mov [IN_POS], rcx
    ret
.finished:
    mov qword [IN_END], 1
.finish:
    mov rax, -1
    ret

; ---- strings ----------------------------------------------------------------
rt_str_equal:                       ; rax, rcx → rax = 1 if the contents are equal
    mov rdx, [rax - 8]
    cmp rdx, [rcx - 8]
    jne .different
    mov rsi, rax
    mov rdi, rcx
    mov rcx, rdx
    repe cmpsb
    jne .different
    mov eax, 1
    ret
.different:
    xor eax, eax
    ret

; ---- error output (!>>): unbuffered, after flushing normal output -----
rt_error_int:
    push rax
    call rt_flush
    pop rax
    sub rsp, 32
    lea rdi, [rsp + 32]
    call rt_decimal
    lea rdx, [rsp + 32]
    sub rdx, rsi
    mov edi, 2
    call rt_write_fd
    add rsp, 32
    ret

rt_error_bool:
    push rax
    call rt_flush
    pop rax
    test rax, rax
    jz .falso_
    lea rsi, [rel s_true]
    mov edx, 4
    jmp .write
.falso_:
    lea rsi, [rel s_false]
    mov edx, 5
.write:
    mov edi, 2
    jmp rt_write_fd

rt_error_str:
    push rax
    call rt_flush
    pop rax
    mov rsi, rax
    mov rdx, [rax - 8]
    mov edi, 2
    jmp rt_write_fd

; ---- arquivos -----------------------------------------------------------------
; rt_read_file: rax = path (STRING) → rax = contents (STRING, with a 0 at the end)
rt_read_file_opt:
    push qword 1                    ; failure → returns 0
    jmp rt_read_file.body
rt_read_file:
    push qword 0                    ; failure → runtime error
.body:
    push rbx
    push r12
    push r13
    sub rsp, 4096                   ; 0-terminated path
    mov byte [rsp], 0
    mov rcx, [rax - 8]
    cmp rcx, 4095
    ja .fail_long
    mov rsi, rax
    mov rdi, rsp
    rep movsb
    mov byte [rdi], 0
    mov eax, 257                    ; sys_openat
    mov rdi, -100                   ; AT_FDCWD
    mov rsi, rsp
    xor edx, edx                    ; O_RDONLY
    syscall
    test rax, rax
    js .fail
    mov r12, rax                    ; fd
    mov eax, 8                      ; sys_lseek(fd, 0, SEEK_END) = size
    mov rdi, r12
    xor esi, esi
    mov edx, 2
    syscall
    test rax, rax
    js .fail
    mov r13, rax                    ; length
    mov eax, 8                      ; back to the start
    mov rdi, r12
    xor esi, esi
    xor edx, edx
    syscall
    lea rcx, [r13 + 8]              ; 8-byte elements for size + 1 bytes
    shr rcx, 3
    call rt_alloc
    mov [rax - 8], r13              ; size in bytes
    push rax
    mov rbx, rax
.read:
    test r13, r13
    jz .got
    xor eax, eax                    ; sys_read
    mov rdi, r12
    mov rsi, rbx
    mov rdx, r13
    syscall
    test rax, rax
    js .fail_reading
    jz .shrank
    add rbx, rax
    sub r13, rax
    jmp .read
.shrank:                          ; the file shrank while being read
    mov rax, [rsp]
    sub [rax - 8], r13
.got:
    mov byte [rbx], 0
    mov eax, 3                      ; sys_close
    mov rdi, r12
    syscall
    pop rax
.back:
    add rsp, 4096
    pop r13
    pop r12
    pop rbx
    add rsp, 8                      ; flag
    ret
.fail_reading:
    pop rax
.fail:
.fail_long:
    cmp qword [rsp + 4096 + 24], 0
    je .fatal
    xor eax, eax                    ; optional: "_"
    jmp .back
.fatal:
    call rt_flush
    mov edi, 2
    lea rsi, [rel s_nihil]
    mov edx, s_nihil_len
    call rt_write_fd
    mov edi, 2
    lea rsi, [rel s_read]
    mov edx, s_read_len
    call rt_write_fd
    mov rsi, rsp                    ; path (cut if it is too long)
    xor edx, edx
.size_path:
    cmp edx, 4095
    jae .write_path
    cmp byte [rsi + rdx], 0
    je .write_path
    inc edx
    jmp .size_path
.write_path:
    mov edi, 2
    call rt_write_fd
    mov edi, 2
    lea rsi, [rel s_quote_nl]
    mov edx, 2
    call rt_write_fd
    mov eax, 60
    mov edi, 2
    syscall

; rt_text: rax = ARRAY of INT → rax = STRING with the low byte of each element
rt_text:
    push rbx
    push r12
    mov rbx, rax
    mov r12, [rax - 8]              ; n
    lea rcx, [r12 + 8]
    shr rcx, 3
    call rt_alloc
    mov [rax - 8], r12
    xor ecx, ecx
.copy:
    cmp rcx, r12
    jae .finish
    mov dl, [rbx + rcx * 8]
    mov [rax + rcx], dl
    inc rcx
    jmp .copy
.finish:
    mov byte [rax + r12], 0
    pop r12
    pop rbx
    ret

; ---- optionals: rax = value, rdx = presence ---------------------------------
rt_print_int_opt:
    test rdx, rdx
    jz rt_print_absent
    jmp rt_print_int
rt_print_bool_opt:
    test rdx, rdx
    jz rt_print_absent
    jmp rt_print_bool
rt_print_str_opt:
    test rdx, rdx
    jz rt_print_absent
    jmp rt_print_str
rt_print_absent:
    lea rsi, [rel s_absent]
    mov edx, 1
    jmp rt_buffer

rt_error_int_opt:
    test rdx, rdx
    jz rt_error_absent
    jmp rt_error_int
rt_error_bool_opt:
    test rdx, rdx
    jz rt_error_absent
    jmp rt_error_bool
rt_error_str_opt:
    test rdx, rdx
    jz rt_error_absent
    jmp rt_error_str
rt_error_absent:
    call rt_flush
    lea rsi, [rel s_absent]
    mov edx, 1
    mov edi, 2
    jmp rt_write_fd

; rt_sleep: rax = milliseconds (≤ 0: returns at once). Flushes the output first,
; so what was written shows up before the wait. Restarts after a signal.
rt_sleep:
    test rax, rax
    jle .done
    push rax
    call rt_flush
    pop rax
    sub rsp, 16                     ; struct timespec { seconds, nanoseconds }
    xor edx, edx
    mov ecx, 1000
    div rcx
    mov [rsp], rax
    imul rdx, rdx, 1000000
    mov [rsp + 8], rdx
.again:
    mov eax, 35                     ; sys_nanosleep(req, rem): rem = req,
    mov rdi, rsp                    ; so an interrupted sleep resumes with
    mov rsi, rsp                    ; the time that was left
    syscall
    cmp rax, -4                     ; -EINTR
    je .again
    add rsp, 16
.done:
    ret

; rt_write_file: rax = path, rcx = text (STRINGs). Creates or replaces the file
; atomically: writes "<path>.nihil-tmp", fsyncs it and renames it over the path,
; so a crash leaves either the old file or the new one, never half of it.
; rt_append_file: same arguments; appends the text (creating the file), then fsyncs.
; rt_write_at: same arguments and rdx = offset; writes the text there (pwrite,
; creating the file, keeping the rest of it), then fsyncs.
; rt_write_at_ns: the same without the fsync (the caller syncs later).
; rt_truncate: rax = path, rdx = size: cuts the file to that size, then fsyncs.
; rt_truncate_ns: the same without the fsync.
; Any failure is a runtime error naming the file and the reason (exit code 2).
%define WF_PATH     0               ; [rsp + WF_PATH]: the path, 0-terminated
%define WF_TEMP     4096            ; [rsp + WF_TEMP]: the temporary path
%define WF_FRAME    8192
%define WF_FLAG     (WF_FRAME + 40) ; 0 replace, 1 append, 2 at an offset, 3 truncate, 4 at an offset without fsync, 5 truncate without fsync
%define WF_OFFSET   (WF_FRAME + 48) ; where the next byte goes (flag 2)
%define WF_MAX_PATH 4080            ; leaves room for ".nihil-tmp" and the 0
rt_write_at:
    push rdx
    push qword 2
    jmp rt_write_file.body
rt_write_at_ns:
    push rdx
    push qword 4
    jmp rt_write_file.body
rt_truncate:
    mov rcx, rax                    ; any STRING: no text is written
    push rdx
    push qword 3
    jmp rt_write_file.body
rt_truncate_ns:
    mov rcx, rax
    push rdx
    push qword 5
    jmp rt_write_file.body
rt_append_file:
    push qword 0
    push qword 1
    jmp rt_write_file.body
rt_write_file:
    push qword 0
    push qword 0
.body:
    push rbx
    push r12
    push r13
    push r14
    push r15
    sub rsp, WF_FRAME
    mov r12, rcx                    ; the text
    mov rbx, [rax - 8]              ; length of the path
    mov rcx, rbx
    cmp rcx, WF_MAX_PATH
    jbe .copy
    mov ecx, WF_MAX_PATH            ; copied cut, only for the message
.copy:
    mov rsi, rax
    lea rdi, [rsp + WF_PATH]
    rep movsb
    mov byte [rdi], 0
    mov rax, -36                    ; ENAMETOOLONG
    cmp rbx, WF_MAX_PATH
    ja .report
    cmp qword [rsp + WF_FLAG], 0
    jne .append
    lea rdi, [rsp + WF_TEMP]        ; temporary = path + ".nihil-tmp"
    lea rsi, [rsp + WF_PATH]
    mov rcx, rbx
    rep movsb
    lea rsi, [rel s_tmp_suffix]
    mov ecx, s_tmp_suffix_len
    rep movsb
    lea r15, [rsp + WF_TEMP]
    mov edx, 0x241                  ; O_WRONLY | O_CREAT | O_TRUNC
    jmp .open
.append:
    lea r15, [rsp + WF_PATH]
    mov edx, 0x441                  ; O_WRONLY | O_CREAT | O_APPEND
    cmp qword [rsp + WF_FLAG], 1
    je .open
    mov edx, 0x41                   ; O_WRONLY | O_CREAT (flags 2 and 4: in place)
    cmp qword [rsp + WF_FLAG], 3
    je .must_exist
    cmp qword [rsp + WF_FLAG], 5
    jne .open
.must_exist:
    mov edx, 1                      ; O_WRONLY (flags 3 and 5: it must exist)
.open:
    mov eax, 257                    ; sys_openat(AT_FDCWD, r15, flags, 0644)
    mov rdi, -100
    mov rsi, r15
    mov r10d, 420
    syscall
    test rax, rax
    js .report
    mov r13, rax                    ; fd
    cmp qword [rsp + WF_FLAG], 3
    je .truncate
    cmp qword [rsp + WF_FLAG], 5
    jne .text
.truncate:
    mov eax, 77                     ; sys_ftruncate(fd, size)
    mov rdi, r13
    mov rsi, [rsp + WF_OFFSET]
    syscall
    test rax, rax
    js .fail_open_fd
    jmp .sync
.text:
    mov rbx, r12                    ; next byte to write
    mov r14, [r12 - 8]              ; bytes left
.write:
    test r14, r14
    jz .sync
    mov eax, 1                      ; sys_write
    mov rdi, r13
    mov rsi, rbx
    mov rdx, r14
    cmp qword [rsp + WF_FLAG], 2
    jb .syscall_write
    mov eax, 18                     ; sys_pwrite64(fd, buf, count, offset)
    mov r10, [rsp + WF_OFFSET]
.syscall_write:
    syscall
    cmp rax, -4                     ; -EINTR: try again
    je .write
    test rax, rax
    js .fail_open_fd
    add [rsp + WF_OFFSET], rax
    add rbx, rax
    sub r14, rax
    jmp .write
.sync:
    cmp qword [rsp + WF_FLAG], 4
    jae .close                      ; flags 4 and 5: no fsync
    mov eax, 74                     ; sys_fsync: the data is on the disk
    mov rdi, r13
    syscall
    test rax, rax
    js .fail_open_fd
.close:
    mov eax, 3                      ; sys_close
    mov rdi, r13
    syscall
    test rax, rax
    js .fail_closed
    cmp qword [rsp + WF_FLAG], 0
    jne .done
    mov eax, 82                     ; sys_rename(temporary, path)
    lea rdi, [rsp + WF_TEMP]
    lea rsi, [rsp + WF_PATH]
    syscall
    test rax, rax
    js .fail_closed
.done:
    add rsp, WF_FRAME
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbx
    add rsp, 16                     ; flag and offset
    ret
.fail_open_fd:
    mov r14, rax
    mov eax, 3                      ; close it anyway
    mov rdi, r13
    syscall
    mov rax, r14
.fail_closed:
    cmp qword [rsp + WF_FLAG], 0
    jne .report
    mov r14, rax
    mov eax, 87                     ; sys_unlink(temporary): leave no debris
    lea rdi, [rsp + WF_TEMP]
    syscall
    mov rax, r14
.report:                            ; rax = -errno
    neg rax
    mov r14, rax
    call rt_flush
    mov edi, 2
    lea rsi, [rel s_nihil]
    mov edx, s_nihil_len
    call rt_write_fd
    mov edi, 2
    lea rsi, [rel s_write]
    mov edx, s_write_len
    call rt_write_fd
    lea rsi, [rsp + WF_PATH]
    xor edx, edx
.size_path:
    cmp byte [rsi + rdx], 0
    je .write_path
    inc edx
    jmp .size_path
.write_path:
    mov edi, 2
    call rt_write_fd
    mov edi, 2
    lea rsi, [rel s_quote_colon]
    mov edx, 3
    call rt_write_fd
    lea rbx, [rel errno_reasons]    ; [errno byte][length byte][text] …, 0 at the end
.find:
    movzx eax, byte [rbx]
    test eax, eax
    jz .unknown
    movzx edx, byte [rbx + 1]
    cmp rax, r14
    je .reason
    lea rbx, [rbx + rdx + 2]
    jmp .find
.reason:
    mov edi, 2
    lea rsi, [rbx + 2]
    call rt_write_fd
    jmp .end
.unknown:
    mov edi, 2
    lea rsi, [rel s_errno]
    mov edx, s_errno_len
    call rt_write_fd
    mov rax, r14
    call rt_error_int               ; the number, on stderr
.end:
    mov edi, 2
    lea rsi, [rel s_nl]
    mov edx, 1
    call rt_write_fd
    mov eax, 60
    mov edi, 2
    syscall

; rt_read_at: rax = path (STRING), rcx = offset, rdx = bytes wanted.
; → rax = a new STRING with the bytes at that offset (fewer at the end of the
;   file, none if the offset is negative or past the end), or 0 if the file
;   does not open; rdx = the file's size (-1 if it does not open).
; rcx = the file's stamp: its st_mtime in nanoseconds mixed with its inode, so it
;   changes when the file is written or replaced (0 if it does not open).
; Reads only those bytes (pread), whatever the size of the file.
rt_read_at:
    push rbx
    push r12
    push r13
    push r14
    push r15
    sub rsp, 4096
    mov r12, rcx                    ; offset
    mov r13, rdx                    ; bytes wanted
    mov rcx, [rax - 8]
    cmp rcx, 4095
    ja .no_file
    mov rsi, rax
    mov rdi, rsp
    rep movsb
    mov byte [rdi], 0
    mov eax, 257                    ; sys_openat(AT_FDCWD, path, O_RDONLY)
    mov rdi, -100
    mov rsi, rsp
    xor edx, edx
    syscall
    test rax, rax
    js .no_file
    mov r14, rax                    ; fd
    mov eax, 5                      ; sys_fstat(fd, buffer): the path is no longer needed
    mov rdi, r14
    mov rsi, rsp
    syscall
    test rax, rax
    js .close_no_file
    mov r15, [rsp + 48]             ; st_size
    imul rax, [rsp + 88], 1000000000 ; the stamp: st_mtime in nanoseconds …
    add rax, [rsp + 96]
    mov rdx, 0x9E3779B97F4A7C15     ; … mixed with st_ino (a rename gives a new file)
    imul rdx, [rsp + 8]
    add rax, rdx
    mov [rsp + 256], rax            ; kept for the return (past the stat buffer)
    xor ecx, ecx                    ; bytes to read: 0 outside the file …
    test r12, r12
    js .count
    cmp r12, r15
    jge .count
    mov rcx, r15                    ; … otherwise min(wanted, size - offset)
    sub rcx, r12
    test r13, r13
    js .count_zero
    cmp rcx, r13
    jbe .count
    mov rcx, r13
    jmp .count
.count_zero:
    xor ecx, ecx
.count:
    mov r13, rcx                    ; bytes to read
    add rcx, 8                      ; 8-byte elements for r13 + 1 bytes
    shr rcx, 3
    call rt_alloc
    mov [rax - 8], r13
    mov rbx, rax
    xor ecx, ecx                    ; read so far
.read:
    cmp rcx, r13
    jae .got
    push rcx
    mov eax, 17                     ; sys_pread64(fd, buf, count, offset)
    mov rdi, r14
    lea rsi, [rbx + rcx]
    mov rdx, r13
    sub rdx, rcx
    lea r10, [r12 + rcx]
    syscall
    pop rcx
    cmp rax, -4                     ; -EINTR: again
    je .read
    test rax, rax
    jle .shrank                     ; error or end: keep what was read
    add rcx, rax
    jmp .read
.shrank:
    mov [rbx - 8], rcx
.got:
    mov rcx, [rbx - 8]
    mov byte [rbx + rcx], 0
    mov eax, 3                      ; sys_close
    mov rdi, r14
    syscall
    mov rax, rbx
    mov rdx, r15
    mov rcx, [rsp + 256]
    jmp .back
.close_no_file:
    mov eax, 3
    mov rdi, r14
    syscall
.no_file:
    xor eax, eax
    mov rdx, -1
    xor ecx, ecx
.back:
    add rsp, 4096
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbx
    ret

; rt_concat: rax = a, rcx = b → rax = new STRING with a followed by b
rt_concat:
    push rbx
    push r12
    push r13
    mov rbx, rax
    mov r12, rcx
    mov r13, [rbx - 8]
    add r13, [r12 - 8]              ; total size
    lea rcx, [r13 + 8]
    shr rcx, 3
    call rt_alloc
    mov [rax - 8], r13
    mov rdi, rax
    mov rsi, rbx
    mov rcx, [rbx - 8]
    rep movsb
    mov rsi, r12
    mov rcx, [r12 - 8]
    rep movsb
    mov byte [rdi], 0
    pop r13
    pop r12
    pop rbx
    ret

; ---- data ------------------------------------------------------------------
s_true:     db "true"
s_absent:  db "_"
s_false:    db "false"
s_maps:       db "/proc/self/maps", 0
s_nihil:      db "nihil: "
s_nihil_len   equ $ - s_nihil
s_nl:       db 10
s_div_zero: db "division by zero", 0
s_size_negativo: db "negative array size", 0
s_size_large:   db "array too large", 0
s_without_memory:  db "out of memory", 0
s_index:   db "index "
s_index_len equ $ - s_index
s_out:     db " out of bounds (size "
s_out_len  equ $ - s_out
s_close_nl: db ")", 10
s_read:      db "could not read '"
s_read_len   equ $ - s_read
s_quote_nl:  db "'", 10
s_write:     db "could not write '"
s_write_len  equ $ - s_write
s_quote_colon: db "': "
s_tmp_suffix: db ".nihil-tmp", 0
s_tmp_suffix_len equ $ - s_tmp_suffix
s_errno:     db "error "
s_errno_len  equ $ - s_errno
%macro REASON 2
    db %1, %%e - %%s
%%s: db %2
%%e:
%endmacro
errno_reasons:
    REASON 2,   "no such file or directory"
    REASON 13,  "permission denied"
    REASON 17,  "file exists"
    REASON 20,  "a part of the path is not a directory"
    REASON 21,  "it is a directory"
    REASON 28,  "no space left on the device"
    REASON 30,  "read-only file system"
    REASON 36,  "the path is too long"
    REASON 122, "disk quota exceeded"
    db 0

; ---- checking the table offsets (assembly fails if they differ) -----
%macro ASSERT_AT 2
    times -(((%1) - start) != (%2)) db 0
%endmacro
ASSERT_AT t_div,          RT_DIV
ASSERT_AT t_mod,          RT_MOD
ASSERT_AT t_print_int,  RT_PRINT_INT
ASSERT_AT t_print_bool, RT_PRINT_BOOL
ASSERT_AT t_print_str,  RT_PRINT_STR
ASSERT_AT t_exit,         RT_EXIT
ASSERT_AT t_error,         RT_ERROR
ASSERT_AT t_alloc,        RT_ALLOC
ASSERT_AT t_array_rep,    RT_ARRAY_REP
ASSERT_AT t_error_index,  RT_ERROR_INDEX
ASSERT_AT t_write_byte, RT_WRITE_BYTE
ASSERT_AT t_read_byte,      RT_READ_BYTE
ASSERT_AT t_str_equal,    RT_STR_EQUAL
ASSERT_AT t_error_int,     RT_ERROR_INT
ASSERT_AT t_error_bool,    RT_ERROR_BOOL
ASSERT_AT t_error_str,     RT_ERROR_STR
ASSERT_AT t_read_file,   RT_READ_FILE
ASSERT_AT t_text,        RT_TEXT
ASSERT_AT t_print_int_opt,  RT_PRINT_INT_OPT
ASSERT_AT t_print_bool_opt, RT_PRINT_BOOL_OPT
ASSERT_AT t_print_str_opt,  RT_PRINT_STR_OPT
ASSERT_AT t_err_int_opt,  RT_ERROR_INT_OPT
ASSERT_AT t_err_bool_opt, RT_ERROR_BOOL_OPT
ASSERT_AT t_err_str_opt,  RT_ERROR_STR_OPT
ASSERT_AT t_read_file_opt,   RT_READ_FILE_OPT
ASSERT_AT t_concat,       RT_CONCAT
ASSERT_AT t_sleep,        RT_SLEEP
ASSERT_AT t_write_file,   RT_WRITE_FILE
ASSERT_AT t_append_file,  RT_APPEND_FILE
ASSERT_AT t_read_at,      RT_READ_AT
ASSERT_AT t_write_at,     RT_WRITE_AT
ASSERT_AT t_write_at_ns,  RT_WRITE_AT_NS
ASSERT_AT t_truncate,     RT_TRUNCATE
ASSERT_AT t_truncate_ns,  RT_TRUNCATE_NS
ASSERT_AT t_int_text,     RT_INT_TEXT
ASSERT_AT t_array_concat, RT_ARRAY_CONCAT
